using System.Net;using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Text.Json.Nodes;using Orbit.Core;
static class ModrinthChecks {
 public static int Run(string root){try{RunAsync(root).GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static async Task RunAsync(string root){Directory.CreateDirectory(root);int checks=0;void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
  byte[] bytes=Encoding.UTF8.GetBytes("independent mock artifact for atomic installer test");string hash=Convert.ToHexString(SHA512.HashData(bytes));var file=new ModArtifact("project","version","Fixture","test.jar","https://cdn.modrinth.com/data/project/versions/version/test.jar",hash,bytes.Length);var plan=new ModPlan("1.20.1","fabric",new[]{file});
  using(var fake=new ModrinthClient(new FakeHandler(bytes))){string dir=Path.Combine(root,"fixture-install");await fake.InstallAsync(plan,dir);Check(File.ReadAllBytes(Path.Combine(dir,"mods/test.jar")).SequenceEqual(bytes),"verified artifact installed");await fake.InstallAsync(plan,dir);Check(Directory.GetFiles(Path.Combine(dir,"mods")).Length==1,"reinstall idempotent");
   bool failed=false;try{await fake.InstallAsync(plan with{Files=new[]{file with{Filename="bad.jar",Sha512=new string('0',128)}}},Path.Combine(root,"bad-hash"));}catch(InvalidDataException){failed=true;}Check(failed&&!Directory.Exists(Path.Combine(root,"bad-hash/mods")),"bad SHA512 publishes no files");
   using var cts=new CancellationTokenSource();cts.Cancel();failed=false;try{await fake.InstallAsync(plan,Path.Combine(root,"cancelled"),ct:cts.Token);}catch(OperationCanceledException){failed=true;}Check(failed&&!Directory.Exists(Path.Combine(root,"cancelled/mods")),"cancelled install publishes no files");
   string conflict=Path.Combine(root,"conflict/mods");Directory.CreateDirectory(conflict);File.WriteAllText(Path.Combine(conflict,"test.jar"),"user mod");failed=false;try{await fake.InstallAsync(plan,Path.GetDirectoryName(conflict)!);}catch(IOException){failed=true;}Check(failed&&File.ReadAllText(Path.Combine(conflict,"test.jar"))=="user mod","existing different JAR preserved");
   foreach(string url in new[]{"http://cdn.modrinth.com/test.jar","https://example.com/test.jar","https://cdn.modrinth.com.evil.invalid/test.jar"}){failed=false;try{ModrinthClient.DownloadUri(url);}catch(InvalidDataException){failed=true;}Check(failed,"untrusted download rejected");}
  }
  using var live=new ModrinthClient();var categories=await live.CategoriesAsync();Check(categories.Any(c=>c.Id=="optimization"),"live API categories");var search=await live.SearchAsync("mod menu","1.20.1","fabric","",0,"relevance");Check(search.Projects.Any(p=>p.Slug=="modmenu"),"live filtered search");var filtered=await live.SearchAsync("","1.20.1","fabric","optimization",0,"downloads");Check(filtered.Projects.Count>0,"live category filter");
  var install=await live.ResolveAsync("modmenu","1.20.1","fabric");Check(install.Files.Count>0&&install.Files.All(f=>f.Filename.EndsWith(".jar")),"live compatible files and dependencies");string real=Path.Combine(root,"real-modmenu");await live.InstallAsync(install,real);Check(install.Files.All(f=>File.Exists(Path.Combine(real,"mods",f.Filename))),"real CDN install with SHA512");await live.InstallAsync(install,real);Check(true,"real repeated install");
  var dependent=await live.ResolveAsync("continuity","1.20.1","fabric");Check(dependent.Files.Count>1,"required dependencies resolved recursively");await live.InstallAsync(dependent,Path.Combine(root,"real-continuity"));Check(true,"dependency set downloaded and committed");
  File.WriteAllText(Path.Combine(root,"live-search.json"),JsonSerializer.Serialize(search));File.WriteAllText(Path.Combine(root,"live-categories.json"),JsonSerializer.Serialize(categories));Console.WriteLine($"PASS {checks} Modrinth checks; games not started; test destination: {root}");
 }
 sealed class FakeHandler(byte[] content):HttpMessageHandler {protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(content)});}
}
